/** Deterministic camera and scene-data seams for the DEV-only island judge. */
import { planIslandDressing, type IslandDressingPlan } from "./island-dressing.js";
import type { IslandBlueprint, IslandPoint } from "./island-blueprint.js";
import { type IslandLookShotId } from "./island-surface-style.js";

export {
  islandLookDebugFromSearch,
  resolveIslandLookDebug,
  ISLAND_LOOK_SHOT_IDS,
  type IslandLookDebugOptions,
  type IslandLookShotId,
} from "./island-surface-style.js";
export { ISLAND_LOOK_CONTRACT } from "./look-contract.js";

export interface IslandLookCameraPose {
  readonly cameraFrom: readonly [number, number, number];
  readonly lookAt: readonly [number, number, number];
  /** Three's spherical polar angle, measured down from the +Y axis. */
  readonly polar: number;
  /** Fixed clockwise yaw from the +Z direction, in radians. */
  readonly azimuth: number;
  readonly fov: number;
  readonly distance: number;
}

export interface IslandLookBounds {
  readonly halfX: number;
  readonly halfZ: number;
  /** The serialised outline lets the design shot fit the actual silhouette. */
  readonly outline?: readonly IslandPoint[];
}

export interface IslandLookViewport {
  readonly width: number;
  readonly height: number;
}

const COURSE_DESIGN_COVERAGE = 0.84;
const COURSE_NEAR_DISTANCE = 18;
const COURSE_FAR_DISTANCE = 54;
// The previous 112-unit envelope left the 53-island field in a narrow middle
// band. Ninety keeps the fixed design shot inside the generated catalogue
// bounds while giving the islands enough screen area to read as the subject.
const WORLD_DESIGN_DISTANCE = 90;
const COURSE_DESIGN_ELEVATION_DEGREES = 24;
const COURSE_DESIGN_TARGET_Y = -1;
const COURSE_DESIGN_AZIMUTH_DEGREES = 65;
const LOOK_POLAR = ((90 - 22) * Math.PI) / 180;
const LOOK_ELEVATION = (22 * Math.PI) / 180;
const COURSE_DESIGN_LOOK_POLAR = ((90 - COURSE_DESIGN_ELEVATION_DEGREES) * Math.PI) / 180;
const COURSE_DESIGN_LOOK_ELEVATION = (COURSE_DESIGN_ELEVATION_DEGREES * Math.PI) / 180;

function finitePositive(value: number, fallback: number): number {
  return Number.isFinite(value) && value > 0 ? value : fallback;
}

function cameraOffset(
  distance: number,
  azimuth = 0,
  elevation = LOOK_ELEVATION,
  targetY = 0,
): readonly [number, number, number] {
  const horizontal = distance * Math.cos(elevation);
  return [
    horizontal * Math.sin(azimuth),
    targetY + distance * Math.sin(elevation),
    horizontal * Math.cos(azimuth),
  ];
}

function designOutline(bounds: IslandLookBounds): readonly IslandPoint[] {
  if (bounds.outline && bounds.outline.length >= 3) return bounds.outline;
  // Tests and small callers may only have extents. An ellipse is a stable
  // fallback that keeps the camera helper deterministic without pretending a
  // rectangle is the island's silhouette.
  return Array.from({ length: 64 }, (_, index) => {
    const angle = (index / 64) * Math.PI * 2;
    return {
      x: Math.cos(angle) * bounds.halfX,
      z: Math.sin(angle) * bounds.halfZ,
    };
  });
}

function projectedDesignExtent(
  bounds: IslandLookBounds,
  viewport: IslandLookViewport,
  fov: number,
  distance: number,
  azimuth: number,
  elevation: number,
  targetY: number,
): { readonly horizontal: number; readonly vertical: number } {
  const aspect = finitePositive(viewport.width / viewport.height, 1);
  const verticalFov = (fov * Math.PI) / 180;
  const horizontalFov = 2 * Math.atan(Math.tan(verticalFov / 2) * aspect);
  const horizontalTangent = Math.tan(horizontalFov / 2);
  const verticalTangent = Math.tan(verticalFov / 2);
  const viewX = Math.sin(azimuth);
  const viewZ = Math.cos(azimuth);
  const rightX = Math.cos(azimuth);
  const rightZ = -Math.sin(azimuth);
  let horizontal = 0;
  let vertical = 0;
  for (const point of designOutline(bounds)) {
    const along = point.x * viewX + point.z * viewZ;
    const relativeY = -targetY;
    const depth = distance - along * Math.cos(elevation) - relativeY * Math.sin(elevation);
    if (depth <= 0) {
      return { horizontal: Number.POSITIVE_INFINITY, vertical: Number.POSITIVE_INFINITY };
    }
    const screenX = (point.x * rightX + point.z * rightZ) / (depth * horizontalTangent);
    const screenY =
      (relativeY * Math.cos(elevation) - along * Math.sin(elevation)) / (depth * verticalTangent);
    horizontal = Math.max(horizontal, Math.abs(screenX));
    vertical = Math.max(vertical, Math.abs(screenY));
  }
  return { horizontal, vertical };
}

function courseDesignDistance(
  bounds: IslandLookBounds,
  viewport: IslandLookViewport,
  fov: number,
  azimuth: number,
  elevation: number,
  targetY: number,
): number {
  let low = COURSE_NEAR_DISTANCE;
  let high = low;
  while (true) {
    const extent = projectedDesignExtent(bounds, viewport, fov, high, azimuth, elevation, targetY);
    if (Math.max(extent.horizontal, extent.vertical) <= COURSE_DESIGN_COVERAGE) break;
    high *= 2;
  }
  for (let iteration = 0; iteration < 40; iteration += 1) {
    const middle = (low + high) / 2;
    const extent = projectedDesignExtent(
      bounds,
      viewport,
      fov,
      middle,
      azimuth,
      elevation,
      targetY,
    );
    if (Math.max(extent.horizontal, extent.vertical) <= COURSE_DESIGN_COVERAGE) high = middle;
    else low = middle;
  }
  return high;
}

/**
 * Return the numeric pose used by a look-contract capture.
 *
 * The design distance is derived only from the serialised outline/bounds and
 * viewport aspect. Near/far and world-design retain fixed distances so those
 * envelope shots can reveal a camera regression instead of hiding it behind
 * refitting.
 */
export function islandLookCameraForShot(
  shot: IslandLookShotId,
  bounds: IslandLookBounds,
  viewport: IslandLookViewport,
): IslandLookCameraPose {
  const fov = viewport.width > 0 && viewport.width < 768 ? 42 : 34;
  const courseDesign = shot === "course-design";
  const azimuth = courseDesign ? (COURSE_DESIGN_AZIMUTH_DEGREES * Math.PI) / 180 : 0;
  const elevation = courseDesign ? COURSE_DESIGN_LOOK_ELEVATION : LOOK_ELEVATION;
  const targetY = courseDesign ? COURSE_DESIGN_TARGET_Y : 0;
  const distance = courseDesign
    ? courseDesignDistance(bounds, viewport, fov, azimuth, elevation, targetY)
    : shot === "course-near"
      ? COURSE_NEAR_DISTANCE
      : shot === "course-far"
        ? COURSE_FAR_DISTANCE
        : WORLD_DESIGN_DISTANCE;
  const offset = cameraOffset(distance, azimuth, elevation, targetY);
  return {
    cameraFrom: offset,
    lookAt: [0, targetY, 0],
    polar: courseDesign ? COURSE_DESIGN_LOOK_POLAR : LOOK_POLAR,
    azimuth,
    fov,
    distance,
  };
}

export interface IslandLookSceneSource {
  readonly detail: "course" | "world";
  readonly blueprints: readonly IslandBlueprint[];
  readonly dressingPlans: readonly IslandDressingPlan[];
  readonly nodePositions: readonly IslandPoint[];
  /** Runtime logical placement count when a detail renderer replaces the old plan. */
  readonly dressingPlacementCount?: number;
  /** Runtime placement count that the detail renderer actually loads as GLB assets. */
  readonly dressingAssetPlacementCount?: number;
  /** Runtime count on the outer island ring, used by the composition metric. */
  readonly dressingRimPlacementCount?: number;
  /** Actual renderer bounds for a detail shot; blueprints may be narrower than a snapped grid. */
  readonly detailBounds?: IslandLookBounds;
}

export interface IslandLookSceneSourceOptions {
  /** Use the actual logical projection count for code metrics. */
  readonly dressingPlacementCount?: number;
  /** Use the actual instanced asset count for readiness. */
  readonly dressingAssetPlacementCount?: number;
  /** Use the actual outer-ring count for the composition metric. */
  readonly dressingRimPlacementCount?: number;
  /** Use the snapped renderer field when fitting a fixed detail camera. */
  readonly detailBounds?: IslandLookBounds;
}

/** Build judge data from the same blueprint and dressing planner as the scene. */
export function islandLookSceneSource(
  detail: "course" | "world",
  blueprints: readonly IslandBlueprint[],
  nodePositions: readonly IslandPoint[] = [],
  options: IslandLookSceneSourceOptions = {},
): IslandLookSceneSource {
  return {
    detail,
    blueprints,
    dressingPlans: blueprints.map((blueprint) => planIslandDressing(blueprint, detail)),
    nodePositions,
    ...(options.dressingPlacementCount === undefined
      ? {}
      : { dressingPlacementCount: options.dressingPlacementCount }),
    ...(options.dressingAssetPlacementCount === undefined
      ? {}
      : { dressingAssetPlacementCount: options.dressingAssetPlacementCount }),
    ...(options.dressingRimPlacementCount === undefined
      ? {}
      : { dressingRimPlacementCount: options.dressingRimPlacementCount }),
    ...(options.detailBounds === undefined ? {} : { detailBounds: options.detailBounds }),
  };
}
